def find_number(n, t):
    min_n_digit = 10 ** (n - 1)
    max_n_digit = 10 ** n - 1
    remainder = min_n_digit % t
    if remainder == 0:
        return min_n_digit
    else:
        num = min_n_digit + (t - remainder)
        if num <= max_n_digit:
            return num
        else:
            return -1

n, t = map(int, input().split())
print(find_number(n, t))

