import random

def is_prime(n, k=5):
    if n < 2: return False
    if n == 2 or n == 3: return True
    if n % 2 == 0: return False

    s, d = 0, n-1
    while d % 2 == 0:
        s, d = s+1, d//2

    for i in range(k):
        a = random.randint(2, n-1)
        x = pow(a, d, n)
        if x == 1 or x == n-1: continue
        for j in range(s-1):
            x = pow(x, 2, n)
            if x == n-1: break
        else: return False
    return True

def goldbach(n):
    for p in range(2, n//2 + 1):
        if is_prime(p) and is_prime(n-p):
            return p, n-p
    return None

def main():
    n = int(input())
    if is_prime(n):
        print(1)
        print(n)
    else:
        if is_prime(n-2):
            print(2)
            print(2, n-2)
        else:
            print(3)
            print(3, *goldbach(n-3))

if __name__ == "__main__":
    main()

