def median_smoothing(n, sequence):
    left = 0
    max_steps = 0
    result_sequence = sequence[:]
    for right in range(1, n):
        if sequence[right] == sequence[right - 1]:
            if right - left > 1:
                length = right - left
                max_steps = max(max_steps, (length - 1) // 2)
                mid = (right + left) // 2
                for i in range(left + 1, mid + 1):
                    result_sequence[i] = sequence[left]
                for i in range(mid + 1, right):
                    result_sequence[i] = sequence[right]
            left = right
    if n - left > 1:
        length = n - left
        max_steps = max(max_steps, (length - 1) // 2)
        mid = (n + left) // 2
        for i in range(left + 1, mid + 1):
            result_sequence[i] = sequence[left]
        for i in range(mid + 1, n):
            result_sequence[i] = sequence[n - 1]
    return max_steps, result_sequence

n = int(input())
sequence = list(map(int, input().split()))
max_steps, result_sequence = median_smoothing(n, sequence)
print(max_steps)
print(' '.join(map(str, result_sequence)))

