import math

def can_reach(x1, y1, x2, y2, v, t, vx, vy, wx, wy, time):
    dx = x2 - x1
    dy = y2 - y1
    if time <= t:
        wind_x = dx - time * vx
        wind_y = dy - time * vy
        distance = math.sqrt(wind_x ** 2 + wind_y ** 2)
        return distance <= time * v
    else:
        wind_x = dx - t * vx - (time - t) * wx
        wind_y = dy - t * vy - (time - t) * wy
        distance = math.sqrt(wind_x ** 2 + wind_y ** 2)
        return distance <= v * t + v * (time - t)

def main():
    x1, y1, x2, y2 = map(int, input().split())
    v, t = map(int, input().split())
    vx, vy = map(int, input().split())
    wx, wy = map(int, input().split())

    left = 0
    right = 1000000000.0
    while right - left > 1e-6:
        mid = (left + right) / 2.0
        if can_reach(x1, y1, x2, y2, v, t, vx, vy, wx, wy, mid):
            right = mid
        else:
            left = mid
    print(right)

if __name__ == "__main__":
    main()

def normalize_email(email):
    local_part, domain = email.split('@')
    domain = domain.lower()
    if domain == 'bmail.com':
        local_part = local_part.lower().split('+')[0].replace('.', '')
    else:
        local_part = local_part.lower()
    return local_part + '@' + domain

def main():
