def count_valid_blocks(k, ai, bi):
    min_value = 10 ** (k - 1)
    max_value = 10 ** k - 1
    count = 0
    for first_digit in range(10):
        if first_digit == bi:
            continue
        start = (min_value // ai + (1 if min_value % ai != 0 else 0)) * ai + (first_digit * 10 ** (k - 1))
        if start > max_value:
            continue
        end = (max_value // ai) * ai + (first_digit * 10 ** (k - 1))
        if end < min_value:
            continue
        count += (end - start) // ai + 1
    return count

def main():
    MOD = 10**9 + 7
    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))
    result = 1
    for ai, bi in zip(a, b):
        result = (result * count_valid_blocks(k, ai, bi)) % MOD
    print(result)

