def calculate_max_length():
    n = int(input())
    words = []
    for _ in range(n):
        words.append(input().strip())

    valid_words = {}
    for word in words:
        letters = set(word)
        if len(letters) <= 2:
            if len(letters) == 0:
                continue
            elif len(letters) == 1:
                letter = list(letters)[0]
                if letter not in valid_words:
                    valid_words[letter] = 0
                valid_words[letter] += len(word)
            else:
                letter1, letter2 = sorted(list(letters))
                pair = (letter1, letter2)
                if pair not in valid_words:
                    valid_words[pair] = 0
                valid_words[pair] += len(word)

    max_length = 0
    for pair in valid_words:
        if isinstance(pair, str):
            max_length = max(max_length, valid_words[pair])
        else:
            max_length = max(max_length, valid_words[pair])
            letter1, letter2 = pair
            max_length = max(max_length, valid_words.get(letter1, 0) + valid_words.get(letter2, 0))
            for letter in pair:
                for other_letter in valid_words:
                    if isinstance(other_letter, tuple) and letter in other_letter:
                        max_length = max(max_length, valid_words[letter] + valid_words[other_letter])

    # Check all pairs of letters
    letters_used = set()
    for word in words:
        letters = set(word)
        if len(letters) <= 2:
            letters_used.update(letters)
    letters = sorted(list(letters_used))
    for i in range(len(letters)):
        for j in range(i, len(letters)):
            total_length = 0
            for word in words:
                word_letters = set(word)
                if len(word_letters) <= 2 and word_letters.issubset({letters[i], letters[j]}):
