from collections import deque

def bfs(graph, n, start, end):
    visited = [False] * (n + 1)
    distance = [-1] * (n + 1)
    queue = deque([start])
    visited[start] = True
    distance[start] = 0

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                queue.append(neighbor)
