import sys

def convex_hull(points):
    points = sorted(set(points))
    if len(points) <= 1:
        return points

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]

def main():
    n, p, q = map(int, sys.stdin.readline().split())
    projects = []
    for _ in range(n):
        a, b = map(int, sys.stdin.readline().split())
        if a > 0 and b > 0:
            projects.append((a, b))

    min_days = float('inf')
    for a, b in projects:
        days = max(p / a, q / b)
        min_days = min(min_days, days)

    hull = convex_hull(projects)
    for i in range(len(hull)):
        a1, b1 = hull[i]
        a2, b2 = hull[(i + 1) % len(hull)]
        denominator = a1 * b2 - a2 * b1
        if denominator != 0:
            x = (p * b2 - q * a2) / denominator
            y = (q * a1 - p * b1) / denominator
            if x >= 0 and y >= 0:
                min_days = min(min_days, x + y)

    print(min_days)

if __name__ == "__main__":
    main()

