def generate_hadamard(k):
    if k == 0:
        return [[1]]
    else:
        prev_hadamard = generate_hadamard(k-1)
        n = len(prev_hadamard)
        hadamard = [[0 for _ in range(2*n)] for _ in range(2*n)]
        for i in range(n):
            for j in range(n):
                hadamard[i][j] = prev_hadamard[i][j]
                hadamard[i][j+n] = prev_hadamard[i][j]
                hadamard[i+n][j] = prev_hadamard[i][j]
                hadamard[i+n][j+n] = -prev_hadamard[i][j]
        return hadamard

def main():
    k = int(input())
    hadamard_matrix = generate_hadamard(k)
    for row in hadamard_matrix:
        print(''.join('+' if x == 1 else '*' for x in row))

if __name__ == "__main__":
    main()

