def split_string(n, p, q, s):
    for a in range(n // p + 1):
        remaining = n - a * p
        if remaining % q == 0 and remaining // q >= 0:
            b = remaining // q
            result = []
            start = 0
            for _ in range(a):
                result.append(s[start:start + p])
                start += p
            for _ in range(b):
                result.append(s[start:start + q])
                start += q
            return len(result), result
    return -1, None

def main():
    n, p, q = map(int, input().split())
    s = input().strip()
    result_length, result = split_string(n, p, q, s)
    if result_length == -1:
        print(-1)
    else:
        print(result_length)
        for substring in result:
            print(substring)

if __name__ == "__main__":
    main()

