import math

def distance(p1, p2):
    """Calculate the Euclidean distance between two points."""
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def distance_to_line_segment(p, p1, p2):
    """Calculate the distance from point p to line segment p1-p2."""
    px, py = p
    x1, y1 = p1
    x2, y2 = p2
    dx, dy = x2 - x1, y2 - y1
    if dx == 0 and dy == 0:
        return distance(p, p1)
    t = max(0, min(1, ((px - x1) * dx + (py - y1) * dy) / (dx**2 + dy**2)))
    nearest_x, nearest_y = x1 + t * dx, y1 + t * dy
    return distance(p, (nearest_x, nearest_y))

def main():
    n, px, py = map(int, input().split())
    p = (px, py)
    vertices = [tuple(map(int, input().split())) for _ in range(n)]

    max_distance = max(distance(p, vertex) for vertex in vertices)
    min_distance = min(min(distance(p, vertex) for vertex in vertices),
                        min(distance_to_line_segment(p, vertices[i], vertices[(i+1) % n]) for i in range(n)))

    area = math.pi * (max_distance**2 - min_distance**2)
    print(area)

if __name__ == "__main__":
    main()

