def solver(ps, s):
	bestDScore = 0
	#bestPrefix = 0
	dScore = 0
	for i in range(len(s)):
		if s[i] == 'A':
			dScore += ps[i]
			if dScore > bestDScore:
				bestDScore = dScore
		elif s[i] == 'B':
			dScore -= ps[i]
		else:
			assert(False)

	dScore = 0
	for i in range(len(s) - 1, -1, -1):
		if s[i] == 'A':
			dScore += ps[i]
			if dScore > bestDScore:
				bestDScore = dScore
		elif s[i] == 'B':
			dScore -= ps[i]
		else:
			assert(False)
	bestScore = calculateScore(ps, s) + bestDScore
	return bestScore

