```python
from collections import defaultdict, deque

def find_overlap(s1, s2):
    for i in range(min(len(s1), len(s2)), 0, -1):
        if s1[-i:] == s2[:i]:
            return i
    return 0

def main():
    n = int(input())
    fragments = [input().strip() for _ in range(n)]
    graph = defaultdict(list)
    in_degree = {frag: 0 for frag in fragments}

    for i in range(n):
        for j in range(n):
            if i != j:
                overlap = find_overlap(fragments[i], fragments[j])
                if overlap > 0:
                    graph[fragments[i]].append((fragments[j], overlap))
                    in_degree[fragments[j]] += 1

    queue = deque([frag for frag in fragments if in_degree[frag] == 0])
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor, _ in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    final_genome = result[0]
    for frag in result[1:]:
        overlap = find_overlap(final_genome, frag)
        final_genome += frag[overlap:]

    print(final_genome)

