def calculate_min_max_distance(n, k, rooms):
    free_rooms = [i for i, room in enumerate(rooms) if room == '0']
    min_max_distance = float('inf')

    left = 0
    for i in range(len(free_rooms)):
        while left < i and free_rooms[i] - free_rooms[left] > free_rooms[i - (k // 2)] - free_rooms[left]:
            left += 1
        max_dist = max(abs(free_rooms[i] - free_rooms[left]), 
                       abs(free_rooms[min(i + k - (i - left), len(free_rooms) - 1)] - free_rooms[i]))
        if i + k - (i - left) >= len(free_rooms):
            max_dist = max(abs(free_rooms[i] - free_rooms[left]), 
                           abs(free_rooms[len(free_rooms) - 1] - free_rooms[i]))
        min_max_distance = min(min_max_distance, max_dist)

    return min_max_distance

