from collections import deque

def process_queries(n, b, queries):
    queue = deque()
    server_busy_until = 0
    results = [-1] * n

    for i, (ti, di) in enumerate(queries):
        # First, check if the server has finished processing the current query by ti
        while queue and server_busy_until <= ti:
            next_di = queue.popleft()[1]
            server_busy_until += next_di

        if server_busy_until <= ti:
            # Server is free
            server_busy_until = ti + di
            results[i] = server_busy_until
        else:
            # Server is busy
            if len(queue) < b:
                queue.append((i, di))
            else:
                # Queue is full, reject the query
                continue

        # Process queries in the queue if the server is done with the current one at ti
        if server_busy_until == ti:
            if queue:
                next_i, next_di = queue.popleft()
                server_busy_until += next_di
                results[next_i] = server_busy_until

    # Process any remaining queries in the queue
    while queue:
        next_di = queue.popleft()[1]
        server_busy_until += next_di
        next_i = queue[0][0] if queue else None
        if next_i is not None:
            results[next_i] = server_busy_until

    return ' '.join(map(str, results))

