def can_print(mid, x, y, pages):
    total_pages = sum(pages[:mid])
    double_sided_used = min(total_pages // 2, x)
    remaining_pages = total_pages - double_sided_used * 2
    return remaining_pages <= y + (x - double_sided_used)

def binary_search(x, y, n, pages):
    low, high = 0, n
    while low <= high:
        mid = (low + high) // 2
        if can_print(mid, x, y, pages):
            low = mid + 1
        else:
            high = mid - 1
    return high

def main():
    n, x, y = map(int, input().split())
    pages = sorted(list(map(int, input().split())))
    print(binary_search(x, y, n, pages))

