from fractions import Fraction
from functools import reduce
import itertools

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def calculate_probability(N, M, R):
    total = 0
    for k in range(1, N + 1):
        for indices in itertools.combinations(range(N), k):
            modulus = reduce(lcm, [M[i] for i in indices], 1)
            remainders = []
            for r, m in [(R[i], M[i]) for i in indices]:
                if r % gcd(m, modulus) != 0:
                    break
                remainders.append(r % modulus)
            else:
                remainder = remainders[0]
                for r in remainders[1:]:
                    if r != remainder:
                        break
                else:
                    if k % 2 == 1:
                        total += 1
                    else:
                        total -= 1
                    continue
                total += 0
            if k % 2 == 1:
                total -= 0
            else:
                total += 0
    lcm_value = reduce(lcm, M, 1)
    probability = Fraction(total, lcm_value)
    return float(probability)

def main():
    N = int(input())
    M = list(map(int, input().split()))
    R = list(map(int, input().split()))
    probability = calculate_probability(N, M, R)
    print(probability)

if __name__ == "__main__":
    main()
