def seating_on_bus(n, m):
    seats = [[0, 0, 0, 0] for _ in range(n)]

    # Fill window seats
    window_seats_count = min(m, 2 * n)
    for i in range(window_seats_count):
        if i % 2 == 0:
            seats[i // 2][0] = i + 1
        else:
            seats[i // 2][3] = i + 1

    # Fill non-window seats
    non_window_seats_count = max(0, m - 2 * n)
    for i in range(non_window_seats_count):
        if i % 2 == 0:
            seats[i // 2][1] = 2 * n + i + 1
        else:
            seats[i // 2][2] = 2 * n + i + 1

    # Generate exit order
    exit_order = []
    for row in seats:
        for seat in row:
            if seat != 0:
                exit_order.append(seat)

    return exit_order


