def solve_rebus():
    rebus = input().strip()
    expression, n = rebus.split('=')
    n = int(n.strip())
    pos_count = 0
    neg_count = 0
    signs = []
    for char in expression:
        if char == '+':
            pos_count += 1
            signs.append(1)
        elif char == '-':
            neg_count += 1
            signs.append(-1)
        elif char == '?':
            if not signs:
                signs.append(1)
                pos_count += 1
    initial_sum = pos_count - neg_count
    values = []
    for sign in signs:
        if initial_sum < n:
            if sign == 1:
                value = min(n - initial_sum, n)
                initial_sum += value
                values.append(value)
            else:
                values.append(1)
        else:
            if sign == 1:
                values.append(1)
            else:
                value = min(initial_sum - n, n)
                initial_sum -= value
                values.append(-value)
    if initial_sum == n:
        print("Possible")
        result = str(abs(values[0]))
        for i in range(1, len(values)):
            operator = '+' if values[i] > 0 else '-'
            result += f" {operator} {abs(values[i])}"
        print(f"{result} = {n}")
