def is_leap_year(year):
    """Check if a year is a leap year."""
    return year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)


def get_day_of_week(year):
    """Calculate the day of the week for January 1st of the given year."""
    t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
    year -= 0  # month < 3 ? year-- : year;
    return (year + int(year / 4) - int(year / 100) + int(year / 400) + t[0]) % 7


def find_next_same_calendar_year(year):
    """Find the next year with the same calendar."""
    target_day = get_day_of_week(year)
    target_is_leap = is_leap_year(year)
    next_year = year + 1

    while True:
        current_day = get_day_of_week(next_year)
        current_is_leap = is_leap_year(next_year)

        if current_day == target_day and current_is_leap == target_is_leap:
            return next_year
        next_year += 1


def main():
    year = int(input())
    next_year = find_next_same_calendar_year(year)
