def largest_cube_root(X):
    low, high = 0, int(X ** (1/3)) + 1
    while low < high:
        mid = (low + high + 1) // 2
        if mid ** 3 <= X:
            low = mid
        else:
            high = mid - 1
    return low

def solve(m, memo = {}):
    if m in memo:
        return memo[m]
    if m == 0:
        return (0, 0)

    a = largest_cube_root(m)
    greedy_choice = (1 + solve(m - a**3, memo)[0], a**3 + solve(m - a**3, memo)[1])
    if a - 1 > 0:
        alternative_choice = solve(a**3 - 1 - (a-1)**3, memo)
        alternative_choice = (1 + alternative_choice[0], (a-1)**3 + alternative_choice[1])
        if (alternative_choice[0] > greedy_choice[0]) or (alternative_choice[0] == greedy_choice[0] and alternative_choice[1] > greedy_choice[1]):
            memo[m] = alternative_choice
            return alternative_choice
    memo[m] = greedy_choice
    return greedy_choice

