import math

def calculate_places(num):
    if num == 1:
        return 1
    else:
        return math.ceil(math.log(num - 1, 7))

def count_valid_pairs(n, m, h_places, m_places):
    from itertools import permutations
    count = 0
    for p in permutations(range(7), h_places + m_places):
        hours = int(''.join(map(str, p[:h_places])), 7)
        minutes = int(''.join(map(str, p[h_places:])), 7)
