class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            self.parent[root_x] = root_y

def main():
    n = int(input())
    a = list(map(int, input().split()))
    uf = UnionFind(n)

    roots = []
    cycle_nodes = set()
    for i in range(n):
        if a[i] - 1 == i:
            roots.append(i)

    for i in range(n):
        if a[i] - 1 != i:
            if uf.find(i) == uf.find(a[i] - 1):
                cycle_nodes.add(i)
            else:
                uf.union(i, a[i] - 1)

    changes = 0
    new_sequence = a[:]

    if len(roots) == 0:
        changes += 1
        roots.append(a[0] - 1 if a[0] - 1 != 0 else 1)
        new_sequence[roots[0]] = roots[0] + 1

    for node in cycle_nodes:
