def dfs(graph, node, visited, universities, count):
    visited[node] = True
    count[node] = universities[node]
    for neighbor in graph[node]:
        if not visited[neighbor]:
            dfs(graph, neighbor, visited, count)
            count[node] += count[neighbor]

def main():
