    university_towns = list(map(int, input().split()))
    universities = {town: 1 for town in university_towns}

    graph = defaultdict(list)
    for _ in range(n - 1):
        x, y = map(int, input().split())
        graph[x].append(y)
        graph[y].append(x)

    visited = [False] * (n + 1)
    count = [0] * (n + 1)
    dfs(graph, 1, visited, universities, count)

    total_distance = 0
    for town in range(1, n + 1):
        for neighbor in graph[town]:
            if neighbor < town:  # To avoid counting edges twice
                continue
            universities_on_town_side = count[town]
            universities_on_neighbor_side = count[neighbor]
            if town in universities:
                universities_on_town_side -= 1  # Adjust count if town is a university
            if neighbor in universities:
                universities_on_neighbor_side -= 1  # Adjust count if neighbor is a university
            pair_count = min(universities_on_town_side, 2 * k - universities_on_town_side)
