def count_pairs(n, nums):
    count = Counter(nums)
    total_count = 0
    for num in nums:
        for power in range(1, 31):
            complement = (1 << power) - num
            if complement in count and complement != num:
                total_count += count[complement]
            elif complement == num:
                total_count += count[complement] - 1
    return total_count // 2

