def shift_string(s):
    s = list(s)
    n = len(s)

    # Find the first character that is not 'a'
    idx = 0
    while idx < n and s[idx] == 'a':
        idx += 1

    # If all characters are 'a', shift the last 'a'
    if idx == n:
        s[n-1] = 'z'
    else:
        # Shift characters from the first non-'a' character backwards
        while idx >= 0 and s[idx] != 'a':
            s[idx] = chr((ord(s[idx]) - ord('a') - 1) % 26 + ord('a'))
            idx -= 1
        # Shift the 'a' that is before the first non-'a' if it exists
        if idx >= 0:
            s[idx] = 'z'

    return ''.join(s)

