import sys
import heapq

def dijkstra(graph, s, t, unknown_weight):
    n = len(graph)
    distances = [sys.maxsize] * n
    distances[s] = 0
    queue = [(0, s)]

    while queue:
        current_distance, current_node = heapq.heappop(queue)
        if current_distance > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node]:
            if weight == 0:
                weight = unknown_weight
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(queue, (distance, neighbor))
    return distances[t]

def main():
    n, m, L, s, t = map(int, input().split())
    edges = []
    graph = [[] for _ in range(n)]

    for _ in range(m):
        u, v, w = map(int, input().split())
        edges.append((u, v, w))
        graph[u].append((v, w))
        graph[v].append((u, w))

    min_length = dijkstra(graph, s, t, 1)
    if min_length > L:
        print("NO")
        return

    max_length = dijkstra(graph, s, t, 10**18)
    if max_length < L:
        print("NO")
        return

    if min_length == max_length:
        if min_length == L:
            print("YES")
            for u, v, w in edges:
                print(u, v, w)
        else:
            print("NO")
        return

    print("YES")
    for u, v, w in edges:
        if w == 0:
            temp_graph = [row[:] for row in graph]
            temp_graph[u] = [(x, y) if x != v else (x, 1) for x, y in temp_graph[u]]
            temp_graph[v] = [(x, y) if x != u else (x, 1) for x, y in temp_graph[v]]
            new_min_length = dijkstra(temp_graph, s, t, 1)
            if new_min_length <= L:
                w = L - min_length + 1
                min_length += w - 1
                print(u, v, w)
            else:
                w = 1
                print(u, v, w)
        else:
            print(u, v, w)

if __name__ == "__main__":
    main()

