def count_falling_positions(n, bumpers):
    count = 0
    left_fall = [False] * n
    right_fall = [False] * n

    # Check from left to right
    if bumpers[0] == '<':
        left_fall[0] = True
        count += 1
    for i in range(1, n):
        if bumpers[i] == '<' and left_fall[i-1]:
            left_fall[i] = True
            count += 1

    # Check from right to left
    if bumpers[n-1] == '>':
        right_fall[n-1] = True
        count += 1
    for i in range(n-2, -1, -1):
        if bumpers[i] == '>' and right_fall[i+1]:
            right_fall[i] = True
            if not left_fall[i]:
                count += 1

    return count

