class tiles:
    def __init__(self, a_string, interest_location):
        n = len(a_string)
        self.half_len = n//2
        self.double_tile = [deque(a_string[:self.half_len]), deque(a_string[n-1:self.half_len-1:-1])]
        if interest_location < self.half_len:
            self.interest_i = 0
            self.interest_j = interest_location
        else:
            self.interest_i = 1
            self.interest_j = n -1 - interest_location

    def shift(self):
        last_element_first = self.double_tile[0].pop()
        first_element_second = self.double_tile[1].popleft()
        self.double_tile[0].appendleft(first_element_second)
        self.double_tile[1].append(last_element_first)
        if self.interest_i == 0 and self.interest_j == self.half_len - 1:
            self.interest_i = 1
        elif self.interest_i == 1 and self.interest_j == 0:
            self.interest_i = 0
        elif self.interest_i == 0:
            self.interest_j += 1
        else:
            self.interest_j -= 1


    def  find_neighbor(self):
        i = self.interest_i
        j = self.interest_j
        if j == 0:
            return self.double_tile[i][j+1] + self.double_tile[(i+1)%2][j+1] + self.double_tile[(i+1)%2][j]
        elif j == self.half_len - 1:
            return self.double_tile[i][j-1] + self.double_tile[(i+1)%2][j-1] + self.double_tile[(i+1)%2][j]
        else:
            return self.double_tile[i][j-1] + self.double_tile[i][j+1] + self.double_tile[(i+1)%2][j-1] + self.double_tile[(i+1)%2][j+1] + self.double_tile[(i+1)%2][j]

    def print_tiles(self):
        print_row = ["", ""]
        for i in range(2):
            for j in range(self.half_len):
                print_row[i] += self.double_tile[i][j]
        for i in range(2):
            print(print_row[i])


