    sizes = list(map(int, input().split()))
    n = int(input())
    participants = []
    for i in range(n):
        line = input().strip()
        if ',' in line:
            preferred_sizes = line.split(',')
            smaller_size = preferred_sizes[0]
            larger_size = preferred_sizes[1]
            size_map = {'S': 0, 'M': 1, 'L': 2, 'XL': 3, 'XXL': 4, 'XXXL': 5}
            smaller_size_index = size_map[smaller_size]
            larger_size_index = size_map[larger_size]
            participants.append((i, smaller_size_index, larger_size_index))
        else:
            size_map = {'S': 0, 'M': 1, 'L': 2, 'XL': 3, 'XXL': 4, 'XXXL': 5}
            size_index = size_map[line]
            participants.append((i, size_index, size_index))

    participants.sort(key=lambda x: (x[1], x[2]))

    assignments = [''] * n
    for participant in participants:
        original_index = participant[0]
        smaller_size_index = participant[1]
        larger_size_index = participant[2]
        if sizes[smaller_size_index] > 0:
            sizes[smaller_size_index] -= 1
            size_map_reverse = {0: 'S', 1: 'M', 2: 'L', 3: 'XL', 4: 'XXL', 5: 'XXXL'}
            assignments[original_index] = size_map_reverse[smaller_size_index]
        elif sizes[larger_size_index] > 0:
            sizes[larger_size_index] -= 1
            size_map_reverse = {0: 'S', 1: 'M', 2: 'L', 3: 'XL', 4: 'XXL', 5: 'XXXL'}
            assignments[original_index] = size_map_reverse[larger_size_index]
        else:
            print('NO')
            return

    print('YES')
    for assignment in assignments:
        print(assignment)

