import bisect

def main():
    n = int(input().strip())
    requests = []
    for _ in range(n):
        s, d = map(int, input().strip().split())
        requests.append((s, d))

    scheduled_repairs = []
    for s, d in requests:
        if not scheduled_repairs or s >= scheduled_repairs[-1][1]:
            # Schedule at s if possible
            start = s
        elif s + d <= scheduled_repairs[0][0]:
            # Schedule at s if it's before the first repair
            start = s
        else:
            # Check if s is available
            idx = bisect.bisect_right([x[0] for x in scheduled_repairs], s)
            available = True
            if idx > 0 and s < scheduled_repairs[idx-1][1]:
                available = False
            if idx < len(scheduled_repairs) and s + d > scheduled_repairs[idx][0]:
                available = False
            if available:
                start = s
            else:
                # Find the first available slot
                start = 1
                for repair in scheduled_repairs:
                    if start + d <= repair[0]:
                        break
                    start = repair[1]
        end = start + d - 1
        bisect.insort(scheduled_repairs, (start, end))
        print(start, end)

