```python
def decode_genome(n, s):
    if n % 4 != 0:
        return '==='

    count = {'A': 0, 'C': 0, 'G': 0, 'T': 0, '?': 0}
    for c in s:
        count[c] += 1

    target_count = n // 4
    for c in 'ACGT':
        if count[c] > target_count:
            return '==='

    need = {'A': target_count - count['A'], 'C': target_count - count['C'], 'G': target_count - count['G'], 'T': target_count - count['T']}
    chars = list(s)
    for i in range(n):
        if chars[i] == '?':
            for c in 'ACGT':
                if need[c] > 0:
                    chars[i] = c
                    need[c] -= 1
                    break

    for c in 'ACGT':
        if need[c] != 0:
            return '==='

    return ''.join(chars)

