def solve(s, t):
    if len(s) != len(t):
        return -1

    mapping = {}
    reverse_mapping = {}
    for i in range(len(s)):
        if s[i] in mapping and mapping[s[i]] != t[i]:
            return -1
        if t[i] in reverse_mapping and reverse_mapping[t[i]] != s[i]:
            return -1
        mapping[s[i]] = t[i]
        reverse_mapping[t[i]] = s[i]

    pairs = [(k, v) for k, v in mapping.items() if k != v and k < v]
