def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    i = 2
    while i * i <= num:
        if num % i == 0:
            return False
        i += 1
    return True

def find_counterexample(n):
    """Find a counterexample to PolandBall's hypothesis."""
    m = 1
    while True:
        result = n * m + 1
        if not is_prime(result):
            return m
        m += 1

def main():
