def unfair_poll(n, m, k, x, y):
    if n == 1:
        sergi_count = k // m + (1 if y <= k % m else 0)
        max_count = k // m + (1 if 1 <= k % m else 0)
        min_count = k // m
        return max_count, min_count, sergi_count

    cycle_count = k // ((n - 1) * 2 * m)
    remaining_questions = k % ((n - 1) * 2 * m)

    count = [[0] * m for _ in range(n)]
    for i in range(n):
        if i == 0 or i == n - 1:
            count[i] = [cycle_count] * m
        else:
            count[i] = [cycle_count * 2] * m

    direction = 1
    current_row = 0
    for _ in range(remaining_questions):
        for j in range(m):
            count[current_row][j] += 1
        if direction == 1:
            if current_row == n - 1:
                direction = -1
                current_row -= 1
            else:
                current_row += 1
        else:
            if current_row == 0:
                direction = 1
                current_row += 1
            else:
                current_row -= 1

    max_count = max(max(row) for row in count)
    min_count = min(min(row) for row in count)
    sergi_count = count[x - 1][y - 1]

    return max_count, min_count, sergi_count

