    column_num = 0
    for i, char in enumerate(reversed(column)):
        column_num += (ord(char) - ord('A') + 1) * (26 ** i)
    return f'R{row}C{column_num}'

def convert_from_rxcy(coord):
    row = ''
    column_num = ''
    reading_row = True
    reading_column = False
    temp = ''
