def homework(s, k):
    char_freq = {}
    for char in s:
        char_freq[char] = char_freq.get(char, 0) + 1

    sorted_freq = sorted(char_freq.items(), key=lambda x: x[1])
    remaining_chars = set()
    for char, freq in sorted_freq:
