from collections import defaultdict, deque

def is_tree(graph, root, cycle_vertices):
    visited = set()
    stack = [root]
    edges = 0
    vertices = 0

    while stack:
        vertex = stack.pop()
        if vertex in visited:
            continue
        visited.add(vertex)
        vertices += 1
        for neighbor in graph[vertex]:
            if neighbor not in cycle_vertices and neighbor not in visited:
                stack.append(neighbor)
                edges += 1

    return vertices == edges + 1 and vertices > 0

def find_simple_cycle(graph, n):
    def dfs(vertex, parent, path):
        for neighbor in graph[vertex]:
            if neighbor == parent:
                continue
            if neighbor in path:
                if len(path) - path.index(neighbor) >= 3:
                    return path[path.index(neighbor):]
            else:
                cycle = dfs(neighbor, vertex, path + [neighbor])
                if cycle:
                    return cycle
        return None

    for i in range(n):
        cycle = dfs(i, -1, [i])
        if cycle:
            return cycle
    return None

