def calc_lcp(s, sa):
    rank = [0 for _ in range(len(s))]
    for i in range(len(s)):
        rank[sa[i]] = i
    lcp = [0 for _ in range(len(s) - 1)]
    h = 0
    for i in range(len(s)):
        if rank[i] < len(s) - 1:
            while max(i, sa[rank[i] + 1]) + h < len(s) and s[i + h] == s[sa[rank[i] + 1] + h]:
                h += 1
            lcp[rank[i]] = h
            if h > 0:
                h -= 1
    return lcp, rank

def suffix_array(s):
    s += '\0'
    sa = [0 for _ in range(len(s))]

