def main():
    n1, n2, k1, k2 = map(int, input().split())
    memo = {}

    def dp(i, j, consecutive, last):
        if (i, j, consecutive, last) in memo:
            return memo[(i, j, consecutive, last)]

        if i == 0 and j == 0:
            return 1

        count = 0
        if last == 0 and i > 0 and consecutive < k1:
            count += dp(i - 1, j, consecutive + 1, 0)
        if last == 1 and i > 0:
