        if last == 1 and j > 0 and consecutive < k2:
            count += dp(i, j - 1, consecutive + 1, 1)
        if last == 0 and j > 0:
            count += dp(i, j - 1, 1, 1)

        count %= MOD
        memo[(i, j, consecutive, last)] = count
        return count

