import math

def is_lucky(n):
    while n > 0:
        digit = n % 10
        if digit not in [4, 7]:
            return False
        n //= 10
    return True

def kth_permutation(n, k):
    if math.factorial(n) < k:
        return -1

    nums = list(range(1, n + 1))
    k -= 1
    permutation = []

    for i in range(n, 0, -1):
        fact = math.factorial(i - 1)
        index = k // fact
        k %= fact
        permutation.append(nums[index])
        nums.pop(index)

    return permutation

def count_lucky_matches(n, k):
    permutation = kth_permutation(n, k)
    if permutation == -1:
        return -1

    count = 0
    for i in range(n):
        if is_lucky(i + 1) and is_lucky(permutation[i]):
            count += 1
    return count

