def base_convert(n, base):
    """Converts a number `n` to a given `base` and returns its digits."""
    digits = []
    while n >= 1:
        digits.append(n % base)
        n = n // base
    return sum(digits)

def gcd(a, b):
    """Calculates the greatest common divisor of `a` and `b`."""
    while b:
        a, b = b, a % b
    return a

def main():
    n = int(input())
    total_sum = sum(base_convert(n, i) for i in range(2, n))
    denominator = n - 2
    g = gcd(total_sum, denominator)
    print(f"{total_sum // g}/{denominator // g}")

