def decimal_to_ternary(n):
    if n == 0:
        return '0'
    ternary = ''
    while n > 0:
        ternary = str(n % 3) + ternary
        n //= 3
    return ternary

def ternary_to_decimal(ternary):
    decimal = 0
    for i, char in enumerate(reversed(ternary)):
        decimal += int(char) * (3 ** i)
    return decimal

def find_b(a, c):
    a_ternary = decimal_to_ternary(a)
    c_ternary = decimal_to_ternary(c)
    max_len = max(len(a_ternary), len(c_ternary))
    a_ternary = a_ternary.zfill(max_len)
    c_ternary = c_ternary.zfill(max_len)
    b_ternary = ''
    for a_digit, c_digit in zip(a_ternary, c_ternary):
        for b_digit in '012':
            if (int(a_digit) + int(b_digit)) % 3 == int(c_digit):
                b_ternary += b_digit
                break
    return ternary_to_decimal(b_ternary)

def main():
