def hopscotch(a, x, y):
    if y % a == 0 or x % a == 0:
        return -1

    row = int(y // a)
    square_in_row = None

    if row % 2 == 0:
        if row == 0:
            return -1 if x < 0 or x >= a else 1
        if (row // 2) % 2 == 0:
            if x < 0 or x >= a:
