def calculate_mask(n):
    """Calculates the mask of a given number n."""
    mask = ''
    for digit in str(n):
        if digit == '4' or digit == '7':
            mask += digit
    return mask

def find_c(a, b):
    """Finds the minimum number c > a such that the mask of c equals b."""
    c = a + 1
    while True:
        if calculate_mask(c) == str(b):
            return c
        c += 1

