def count_palindromic_pairs(s):
    n = len(s)
    dp = [[False] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = True
    for i in range(n - 1):
        if s[i] == s[i + 1]:
            dp[i][i + 1] = True
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and dp[i + 1][j - 1]:
                dp[i][j] = True

    count = [0] * n
    count[0] = 1
    for i in range(1, n):
        count[i] = count[i - 1]
        for j in range(i + 1):
            if dp[j][i]:
                count[i] += 1

    total_pairs = 0
    for i in range(n):
        for j in range(i, n):
            if dp[i][j]:
                total_pairs += count[i - 1] if i > 0 else 0

    return total_pairs

