def find_period(a, b, m, r0):
    seen = {}
    r = r0
    i = 0
    while r not in seen:
        seen[r] = i
        r = (a * r + b) % m
        i += 1
    # Now r is the first repeated value, and seen[r] is its first occurrence index
    # The period is i - seen[r]
    return i - seen[r]

