    vertices.add((vertex[0], vertex[1] - 1))
  return vertices


def bfs(*start):
  stack, visited = [(start, 0)], set()
  while stack:
    vertex, time = stack.pop(0)
    if vertex[1] >= n:
      return 1
    if vertex not in visited:
      visited.add(vertex)
      for neighbour in neighbours(vertex, time):
        if neighbour not in visited:
          stack.append((neighbour, time + 1))
  return 0


