from collections import deque

def can_escape(n, k, left_wall, right_wall):
    queue = deque([(0, 0, 0)])  # wall (0=left, 1=right), height, time
    visited = set([(0, 0, 0)])

    while queue:
        wall, height, time = queue.popleft()

        if height > n:
            return True

        if height <= time:
            continue

        # Climb up
        new_height = height + 1
        if new_height <= n and [left_wall, right_wall][wall][new_height-1] == '-' and (wall, new_height, time+1) not in visited:
            queue.append((wall, new_height, time+1))
            visited.add((wall, new_height, time+1))

        # Climb down
        new_height = height - 1
        if new_height >= 0 and [left_wall, right_wall][wall][new_height] == '-' and (wall, new_height, time+1) not in visited:
            queue.append((wall, new_height, time+1))
            visited.add((wall, new_height, time+1))

        # Jump
        new_height = height + k
        new_wall = 1 - wall
        if new_height <= n and [left_wall, right_wall][new_wall][new_height-1] == '-' and (new_wall, new_height, time+1) not in visited:
            queue.append((new_wall, new_height, time+1))
            visited.add((new_wall, new_height, time+1))
        elif new_height > n:
            return True

    return False

def main():
