import re

def parse_procedures(n):
    procedures = {}
    for _ in range(n):
        line = input().strip()
        match = re.match(r'\s*void\s+([a-zA-Z0-9]+)\s*\(\s*(.*?)\s*\)\s*', line)
        name, params = match.groups()
        params = [p.strip() for p in params.split(',')]
        if name not in procedures:
            procedures[name] = []
        procedures[name].append(params)
    return procedures

def parse_variables(m):
    variables = {}
    for _ in range(m):
        line = input().strip()
        match = re.match(r'\s*(\w+)\s+([a-zA-Z0-9]+)\s*', line)
        var_type, var_name = match.groups()
        variables[var_name] = var_type
    return variables

def parse_calls(k):
    calls = []
    for _ in range(k):
        line = input().strip()
        match = re.match(r'\s*([a-zA-Z0-9]+)\s*\(\s*(.*?)\s*\)\s*', line)
        name, params = match.groups()
        params = [p.strip() for p in params.split(',')]
        calls.append((name, params))
    return calls

def count_suitable_procedures(procedures, variables, calls):
    results = []
    for name, params in calls:
        count = 0
        if name in procedures:
            for proc_params in procedures[name]:
                if len(proc_params) == len(params):
                    match = True
                    for proc_param, var_name in zip(proc_params, params):
                        var_type = variables[var_name]
                        if proc_param != 'T' and proc_param != var_type:
                            match = False
                            break
                    if match:
                        count += 1
        results.append(count)
    return results

def main():
    n = int(input())
    procedures = parse_procedures(n)
    m = int(input())
    variables = parse_variables(m)
    k = int(input())
    calls = parse_calls(k)
    results = count_suitable_procedures(procedures, variables, calls)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()

