def main():
    n = int(input())
    computer = list(map(int, input().split()))
    graph = defaultdict(list)
    in_degree = [0] * n

    for i in range(n):
        dependencies = list(map(int, input().split()))
        k = dependencies[0]
        in_degree[i] = k
        for j in range(1, k + 1):
            graph[dependencies[j] - 1].append(i)

    order = topological_sort(graph, in_degree)
    dp = [[0] * 3 for _ in range(n)]

