        part = order[i]
        for prev_comp in range(3):
            if i > 0:
                move_time = get_move_time(prev_comp, computer[part] - 1)
                dp[i][computer[part] - 1] = min(dp[i][computer[part] - 1], dp[i-1][prev_comp] + move_time)
            else:
                dp[i][computer[part] - 1] = 0
        dp[i][computer[part] - 1] += 1

    min_time = min(dp[-1])
    print(min_time)

def topological_sort(graph, in_degree):
    queue = deque([i for i in range(len(in_degree)) if in_degree[i] == 0])
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
    return order

