def calculate_adjacency_matrix(k):
    target = k
    n = 0
    while (n * (n - 1) * (n - 2)) // 6 < target:
        n += 1
    if (n * (n - 1) * (n - 2)) // 6 == target:
        matrix = [[0 for _ in range(n)] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    matrix[i][j] = 1
        return matrix
    else:
        n -= 1
        excess = target - (n * (n - 1) * (n - 2)) // 6
        matrix = [[0 for _ in range(n + excess * 2)] for _ in range(n + excess * 2)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    matrix[i][j] = 1
        for i in range(excess):
            matrix[n + 2 * i][n + 2 * i + 1] = matrix[n + 2 * i + 1][n + 2 * i] = 1
            matrix[n + 2 * i][n + i % n] = matrix[n + i % n][n + 2 * i] = 1
            matrix[n + 2 * i + 1][n + i % n] = matrix[n + i % n][n + 2 * i + 1] = 1
        return matrix

