def restore_ipv6_address(short_address):
    if "::" not in short_address:
        blocks = short_address.split(":")
        padded_blocks = [block.zfill(4) for block in blocks]
        return ":".join(padded_blocks)

    left, right = short_address.split("::")
    left_blocks = left.split(":") if left else []
    right_blocks = right.split(":") if right else []
    num_zero_blocks = 8 - len(left_blocks) - len(right_blocks)

    padded_left_blocks = [block.zfill(4) for block in left_blocks]
    padded_right_blocks = [block.zfill(4) for block in right_blocks]
    zero_blocks = ["0000"] * num_zero_blocks

    return ":".join(padded_left_blocks + zero_blocks + padded_right_blocks)


