def sieve_of_eratosthenes(n):
    """Generate prime numbers up to n."""
    sieve = [True] * (n + 1)
    sieve[0:2] = [False, False]  # 0 and 1 are not prime numbers
    for current_prime in range(2, int(n ** 0.5) + 1):
        if sieve[current_prime]:
            for multiple in range(current_prime * current_prime, n + 1, current_prime):
                sieve[multiple] = False
    return [num for num, is_prime in enumerate(sieve) if is_prime]

def count_almost_primes(n):
    """Count almost prime numbers up to n."""
    primes = sieve_of_eratosthenes(n)
    count = 0
    for num in range(1, n + 1):
        distinct_prime_divisors = set()
        for prime in primes:
            if prime > num:
                break
            if num % prime == 0:
                distinct_prime_divisors.add(prime)
        if len(distinct_prime_divisors) == 2:
            count += 1
    return count

