def prime_factors(n):
    """Returns a dictionary of prime factors and their powers"""
    factors = {}
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors[i] = factors.get(i, 0) + 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def euler_totient(n):
    """Computes Euler's totient function"""
    factors = prime_factors(n)
    result = n
    for p in factors:
        result *= (1 - 1/p)
    return int(result)

def main():
