MOD = 1000000007

def binomial_coefficient(n, k):
    if k > n:
        return 0
    result = 1
    for i in range(1, k + 1):
        result = (result * (n - i + 1)) % MOD
        result = (result * pow(i, MOD - 2, MOD)) % MOD
    return result

def derangement(n):
    der = [0] * (n + 1)
    der[0] = 1
    der[1] = 0
    for i in range(2, n + 1):
        der[i] = ((i - 1) * (der[i - 1] + der[i - 2])) % MOD
    return der

def main():
    n, k = map(int, input().split())
    der = derangement(n)
    ans = 0
    for m in range(k + 1):
        if 2 * m > n or k - m > n - 2 * m:
            continue
        ways_to_choose_m_pairs = binomial_coefficient(n - 1, 2 * m) * (pow(2, m, MOD)) % MOD
        ways_to_choose_k_m_from_rest = binomial_coefficient(n - 2 * m, k - m)
        ways_to_derange_rest = der[n - 2 * m - (k - m)]
        ans = (ans + ways_to_choose_m_pairs * ways_to_choose_k_m_from_rest * ways_to_derange_rest) % MOD
    print(ans)

