def determine_topology(n, m, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    degrees = [len(graph[i]) for i in range(n)]

    bus = sum(1 for d in degrees if d == 1) == 2 and all(d == 1 or d == 2 for d in degrees)
    ring = all(d == 2 for d in degrees)
    star = sum(1 for d in degrees if d == 1) == n-1 and sum(1 for d in degrees if d == n-1) == 1

    if bus and m == n-1:
        return "bus topology"
    elif ring and m == n:
        return "ring topology"
    elif star and m == n-1:
        return "star topology"
    else:
        return "unknown topology"

