def ip_to_int(ip):
    parts = list(map(int, ip.split('.')))
    return (parts[0] << 24) + (parts[1] << 16) + (parts[2] << 8) + parts[3]

def int_to_ip(n):
    return '.'.join([str((n >> 24) & 255), str((n >> 16) & 255), str((n >> 8) & 255), str(n & 255)])

def count_distinct_networks(ips, prefix_length):
    mask = (1 << 32) - (1 << (32 - prefix_length))
    prev = None
    count = 0
    for ip in ips:
        network = ip & mask
        if network != prev:
            count += 1
            prev = network
    return count

