def floyd_warshall(graph):
    distance = [[float('inf')] * 26 for _ in range(26)]
    for i in range(26):
        distance[i][i] = 0
    for u, v, w in graph:
        distance[u][v] = min(distance[u][v], w)
    for k in range(26):
        for i in range(26):
            for j in range(26):
                distance[i][j] = min(distance[i][j], distance[i][k] + distance[k][j])
