	for r in interval(bound2 + 1, min(M, d + N)):
		ans += 2 * (d + N - r) + 2
	if (M <= d + N):
		return ans
	for r in interval(d + N + 1, M):
		ans += 1
	return ans

def case2(N, M, d):
	return partA(N, M, d) + partB(N, M, d)

def remain(N, M, d):
	if (M >= d + N):
		return 1
	if (M > d):
		return d + N - M + 1
	if (M <= d):
		return N + 1

def calc(N, M, d):
	if (N <= d):
		return remain(N, M, d) + case1(N, M, d)
	else:
		return remain(N, M, d) + case2(N, M, d)

print(calc(N, M, d))

