from collections import deque

def apply_operations(state):
    a, b, c, d = state
    next_states = []
    # Define the operations
    operations = [
        ((a+1, b+1, c, d), ('+', 1)),
        ((a, b+1, c+1, d), ('+', 2)),
        ((a, b, c+1, d+1), ('+', 3)),
        ((a+1, b, c, d+1), ('+', 4)),
    ]
    if a % 2 == 0 and b % 2 == 0:
        next_states.append(((a//2, b//2, c, d), ('/', 1)))
    if b % 2 == 0 and c % 2 == 0:
        next_states.append(((a, b//2, c//2, d), ('/', 2)))
    if c % 2 == 0 and d % 2 == 0:
        next_states.append(((a, b, c//2, d//2), ('/', 3)))
    if d % 2 == 0 and a % 2 == 0:
        next_states.append(((a//2, b, c, d//2), ('/', 4)))
    next_states.extend(operations)
    return next_states

def crack_safe(nums):
    target = (1, 1, 1, 1)
    queue = deque([(nums, [])])
    visited = set([nums])
    while queue:
        state, path = queue.popleft()
        if state == target:
            return '\n'.join([op[0] + str(op[1]) for op in path])
        for next_state, op in apply_operations(state):
            if next_state not in visited:
                visited.add(next_state)
                queue.append((next_state, path + [op]))
    return '-1'

