import heapq

def dancing_lessons(n, genders, skills):
    couples = []
    positions = list(range(1, n + 1))
    removed = [False] * n

    heap = []
    for i in range(n - 1):
        if genders[i] != genders[i + 1]:
            heapq.heappush(heap, (abs(skills[i] - skills[i + 1]), i, i + 1))

    while heap:
        diff, left, right = heapq.heappop(heap)
        if not removed[left] and not removed[right]:
            couples.append(f'{min(positions[left], positions[right])} {max(positions[left], positions[right])}')
            removed[left] = removed[right] = True

            if left > 0 and not removed[left - 1]:
                new_right = right + 1 if right + 1 < n and not removed[right + 1] else left - 1
                if genders[left - 1] != genders[new_right]:
                    heapq.heappush(heap, (abs(skills[left - 1] - skills[new_right]), left - 1, new_right))
            if right < n - 1 and not removed[right + 1]:
                new_left = left - 1 if left - 1 >= 0 and not removed[left - 1] else right + 1
                if genders[right + 1] != genders[new_left]:
                    heapq.heappush(heap, (abs(skills[right + 1] - skills[new_left]), new_left, right + 1))

    return len(couples), '\n'.join(couples)

