def min_swaps(n, animals):
    h_count = animals.count('H')
    t_count = n - h_count
    double_animals = animals + animals

    min_swaps_h = float('inf')
    current_t = 0
    for i in range(2 * n):
        if double_animals[i] == 'T':
            current_t += 1
        if i >= h_count:
            if double_animals[i - h_count] == 'T':
                current_t -= 1
        if i >= h_count - 1:
            min_swaps_h = min(min_swaps_h, current_t)

    min_swaps_t = float('inf')
    current_h = 0
    for i in range(2 * n):
        if double_animals[i] == 'H':
            current_h += 1
        if i >= t_count:
            if double_animals[i - t_count] == 'H':
                current_h -= 1
        if i >= t_count - 1:
            min_swaps_t = min(min_swaps_t, current_h)

    return min(min_swaps_h, min_swaps_t)

