            prefix_sum[i][j] = prefix_sum[i-1][j] + prefix_sum[i][j-1] - prefix_sum[i-1][j-1] + grid[i-1][j-1]
    return prefix_sum

def count_trees(prefix_sum, x1, y1, x2, y2):
    return prefix_sum[x2][y2] - prefix_sum[x1][y2] - prefix_sum[x2][y1] + prefix_sum[x1][y1]

def main():
    n, m = map(int, input().split())
    grid = [list(map(int, input().split())) for _ in range(n)]
    a, b = map(int, input().split())

    prefix_sum = calculate_prefix_sum(grid, n, m)

    min_trees_ab = float('inf')
    for i in range(n - a + 1):
        for j in range(m - b + 1):
            min_trees_ab = min(min_trees_ab, count_trees(prefix_sum, i, j, i + a, j + b))

    min_trees_ba = float('inf')
    for i in range(n - b + 1):
        for j in range(m - a + 1):
            min_trees_ba = min(min_trees_ba, count_trees(prefix_sum, i, j, i + b, j + a))

    print(min(min_trees_ab, min_trees_ba))

