def construct_crossword(words):
    for w1, w2, w3, w4, w5, w6 in [words, [words[0], words[2], words[1], words[3], words[4], words[5]]]:
        for h1, h2, v1, v2, v3, v4 in [
            (w1, w2, w3, w4, w5, w6), (w1, w2, w3, w5, w4, w6), (w1, w2, w3, w6, w4, w5),
            (w2, w1, w3, w4, w5, w6), (w2, w1, w3, w5, w4, w6), (w2, w1, w3, w6, w4, w5)
        ]:
            if (len(h1) >= 3 and len(h2) >= 3 and len(v1) >= 3 and len(v2) >= 3 and 
                len(v3) >= 3 and len(v4) >= 3):
                if (h1[0] == v1[0] and h1[-1] == v2[0] and 
                    h2[0] == v3[-1] and h2[-1] == v4[-1] and 
