def rotate_amulet(amulet):
    """Rotate the amulet 90 degrees clockwise."""
    return [list(reversed(i)) for i in zip(*amulet)]

def normalize_amulet(amulet):
    """Normalize the amulet by returning its lexicographically smallest rotation."""
    rotations = [amulet]
    for _ in range(3):
        rotations.append(rotate_amulet(rotations[-1]))
    return min([tuple(tuple(row) for row in rotation) for rotation in rotations])

