import sys

def can_cover(x, d):
    count = 0
    left = x[0]
    i = 0
    while i < len(x):
        right = x[i] + 2 * d
        count += 1
        while i < len(x) and x[i] <= right:
            i += 1
        if i < len(x):
            left = x[i]
    return count <= 3

