def parse(s):
    stack = []
    i = 0
    while i < len(s):
        if s[i].isalpha():
            j = i + 1
            while s[j] != ':' and s[j] != '.' and s[j] != ',':
                j += 1
            name = s[i:j]
            i = j
            if s[i] == ':':
