def can_achieve(target, energies, n, k):
    total_transfer_in = 0
    total_transfer_out = 0
    for energy in energies:
        if energy < target:
            total_transfer_in += target - energy
        else:
            total_transfer_out += energy - target
    transfer_out_after_loss = total_transfer_out * (1 - k / 100)
    return total_transfer_in <= transfer_out_after_loss

def binary_search(energies, n, k):
    low = 0
    high = max(energies)
    while high - low > 1e-9:
        mid = (low + high) / 2
        if can_achieve(mid, energies, n, k):
            low = mid
        else:
            high = mid
    return low

