import math

def extended_euclidean(a, b):
    """Compute the GCD of a and b using the Extended Euclidean Algorithm"""
    a1, b1 = abs(a), abs(b)
    xa, ya, xb, yb = math.copysign(1, a), 0, 0, math.copysign(1, b)
    if a1 < b1:
        a1, b1 = b1, a1
        xa, ya, xb, yb = xb, yb, xa, ya
    while b1 > 0:
        k = a1 // b1
        xa, ya, xb, yb = xb, yb, xa - k * xb, ya - k * yb
        a1, b1 = b1, a1 % b1
    return int(a1), int(-xa), int(-ya)

def main():
    a, b, c = map(int, input().split())
    gcd, x_coeff, y_coeff = extended_euclidean(a, b)
    if c % gcd != 0:
        print(-1)
    else:
        x = x_coeff * (c // gcd)
        y = y_coeff * (c // gcd)
        print(x, y)

if __name__ == "__main__":
