def intersect(a, b):
    dif = b[0] - a[0]
    dist = abs(dif)
    if dist > a[1] + b[1] + 1e-10:   # Conservative with this case
        return 0
    if dist <= abs(a[1] - b[1]) - 1e-10:
        return 1
    k = (dist * dist + a[1] * a[1] - b[1] * b[1]) / (2 * dist)
    u = dif * k / dist
    v = dif * 1j / dist * (a[1] * a[1] - k * k) ** 0.5
    return [a[0]+u+v, a[0]+u-v]

