def generate_binary_strings(n):
    return [bin(i)[2:].zfill(n) for i in range(2**n)]

def are_equivalent(s1, s2, n):
    # Check for color replacement and/or string turnover
    rev_s1 = s1[::-1]
    comp_s1 = ''.join('1' if c == '0' else '0' for c in s1)
    rev_comp_s1 = comp_s1[::-1]
    return s1 in [s2, rev_s1, comp_s1, rev_comp_s1]

def find_min_string(strings):
    return min(strings)

def main():
    n, k = map(int, input().split())
    all_strings = generate_binary_strings(n)
    equivalence_classes = []
    processed = set()

    for s in all_strings:
        if s in processed:
            continue
        equivalence_class = [s]
        processed.add(s)
        for other_s in all_strings:
            if other_s == s or other_s in processed:
                continue
            if are_equivalent(s, other_s, n):
                equivalence_class.append(other_s)
                processed.add(other_s)
        equivalence_classes.append(equivalence_class)

    min_strings = [find_min_string(class_strings) for class_strings in equivalence_classes]
    min_strings.sort()

    if k > len(min_strings):
        print(-1)
    else:
        print(min_strings[k-1])

if __name__ == "__main__":
    main()

