import math

def is_prime(num):
    """Check if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def next_prime(n):
    """Find the next prime number after n."""
    num = n + 1
    while not is_prime(num):
        num += 1
    return num

def main():
    """Main function to solve the problem."""
    n, m = map(int, input().split())
    next_n = next_prime(n)
    if next_n == m:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()

