    xs, ys = map(int, sys.stdin.readline().split())
    n = int(sys.stdin.readline())
    objects = []
    for _ in range(n):
        x, y = map(int, sys.stdin.readline().split())
        objects.append((x, y))

    distances = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        if i == 0:
            x1, y1 = xs, ys
        else:
            x1, y1 = objects[i - 1]
        for j in range(n + 1):
            if j == 0:
                x2, y2 = xs, ys
