def classify_triad(notes):
    """Classify a triad as major, minor, or strange."""
    for permutation in itertools.permutations(notes):
        first, second, third = permutation
        distance1 = calculate_distance(first, second)
        distance2 = calculate_distance(second, third)
        if distance1 == 4 and distance2 == 3:
            return "major"
        elif distance1 == 3 and distance2 == 4:
            return "minor"
    return "strange"

