from collections import deque

def main():
    n, m, k = map(int, input().split())
    maze = []
    start = None
    for i in range(n):
        row = list(input().strip())
        maze.append(row)
        if 'X' in row:
            start = (i, row.index('X'))

    directions = {'D': (1, 0), 'L': (0, -1), 'R': (0, 1), 'U': (-1, 0)}
    moves = ['D', 'L', 'R', 'U']

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and maze[x][y] != '*'

    queue = deque([(start, '')])
    visited = set([start])
    ans = None

    while queue:
        (x, y), path = queue.popleft()
        if len(path) == k:
            if (x, y) == start:
                if ans is None or path < ans:
                    ans = path
            continue
        for move in moves:
            dx, dy = directions[move]
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                new_path = path + move
                queue.append(((nx, ny), new_path))
                if len(new_path) <= k:
                    visited.add((nx, ny))

    if ans is None:
        print('IMPOSSIBLE')
    else:
        print(ans)

