def preprocess_table(n, m, table):
    max_reachable = [0] * n
    column_max_reachable = [[0] * m for _ in range(n)]

    for j in range(m):
        column_max_reachable[n-1][j] = n-1
        for i in range(n-2, -1, -1):
            if table[i][j] <= table[i+1][j]:
                column_max_reachable[i][j] = column_max_reachable[i+1][j]
            else:
                column_max_reachable[i][j] = i

    for i in range(n):
        max_reachable[i] = max(column_max_reachable[i])

    return max_reachable

def answer_queries(n, max_reachable, queries):
    answers = []
    for l, r in queries:
        l -= 1
        r -= 1
        answers.append(max_reachable[l] >= r)
    return answers

if __name__ == "__main__":
    main()

