from collections import defaultdict

def calculate_powers(k, limit):
    powers = set()
    if k == 1:
        powers.add(1)
    elif k == -1:
        powers.add(1)
        powers.add(-1)
    else:
        val = 1
        while abs(val) <= limit:
            powers.add(val)
            val *= k
    return powers

def solve():
    n, k = map(int, input().split())
    affection_values = list(map(int, input().split()))

    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + affection_values[i]

    limit = 10**15
    powers = calculate_powers(k, limit)

    count_map = defaultdict(int)
    count_map[0] = 1

    total_count = 0
    for i in range(1, n + 1):
        total_count += count_map[prefix_sum[i] - 1]
        for power in powers:
            if prefix_sum[i] - power in count_map:
                total_count += count_map[prefix_sum[i] - power]
        count_map[prefix_sum[i]] += 1

    return total_count

