    for first_option, _, idx in clubs:
        first_options[first_option].append(idx)

    conflicting_clubs = set()
    for club_idx_list in first_options.values():
        if len(club_idx_list) > 1:
            for idx in club_idx_list:
                conflicting_clubs.add(idx)

    graph = defaultdict(list)
    conflicting_club_map = {}
    for club in clubs:
        if club[2] in conflicting_clubs:
            conflicting_club_map[club[2]] = club

    for i in range(n):
