            for j in range(i + 1, n):
                if j in conflicting_clubs:
                    if conflicting_club_map[i][0] == conflicting_club_map[j][0]:
                        graph[i].append(j)
                        graph[j].append(i)

    colors = {}
    def is_bipartite(node):
        queue = deque([node])
        colors[node] = 1
        while queue:
            current_node = queue.popleft()
            for neighbor in graph[current_node]:
                if neighbor in colors:
                    if colors[neighbor] == colors[current_node]:
                        return False
                else:
                    colors[neighbor] = 3 - colors[current_node]
                    queue.append(neighbor)
