import math

def get_height(n):
    return int(math.log(n + 1, 2))

def get_parent(u, height):
    depth = get_depth(u, height)
    if depth == 0:
        return u
    parent_depth = depth - 1
    offset = u - (2 ** depth - 1)
    parent_offset = offset // 2
    return 2 ** parent_depth - 1 + parent_offset

def get_left_child(u, height):
    depth = get_depth(u, height)
    max_depth = height - 1
    if depth == max_depth:
        return u
    left_child_depth = depth + 1
    offset = u - (2 ** depth - 1)
    left_child_offset = offset * 2
    return 2 ** left_child_depth - 1 + left_child_offset

def get_right_child(u, height):
    depth = get_depth(u, height)
    max_depth = height - 1
    if depth == max_depth:
        return u
    right_child_depth = depth + 1
    offset = u - (2 ** depth - 1)
    right_child_offset = offset * 2 + 1
    return 2 ** right_child_depth - 1 + right_child_offset

def get_depth(u, height):
    for d in range(height):
        if u < 2 ** (d + 1):
