def clean_trailing_zeros(a):
    if not a:
        return a

    i = len(a) - 1
    while i >= 1 and a[i] == 0:
        i -= 1

    return a[:i + 1]


def remove_digits(a, i1, i2):
    if i1:
        i1 = i1[0]
        result1 = clean_trailing_zeros(a[:i1] + a[i1 + 1:])
    else:
        result1 = []

    if len(i2) >= 2:
        i21, i22 = i2[:2]
        result2 = clean_trailing_zeros(a[:i21] + a[i21 + 1:i22] + a[i22 + 1:])
    else:
        result2 = []

    if len(result1) > len(result2):
        return result1
    else:
        return result2


def main():
    a = map(int, input())
    a = list(a)[::-1]

    if len(a) == 1:
        a = a[0]
        if a % 3 == 0:
            return a
        else:
            return -1

    a_mod_3 = [x % 3 for x in a]
    sum_mod_3 = sum(a) % 3

    if sum_mod_3 == 0:
        return ''.join(map(str, a[::-1]))

    if sum_mod_3 == 1:
        i1 = [i for i, x in enumerate(a_mod_3) if x == 1]
        i2 = [i for i, x in enumerate(a_mod_3) if x == 2]
    else:
        i1 = [i for i, x in enumerate(a_mod_3) if x == 2]
        i2 = [i for i, x in enumerate(a_mod_3) if x == 1]

    result = remove_digits(a, i1, i2)
    if result:
        return ''.join(map(str, result[::-1]))
    else:
        return -1


if __name__ == '__main__':
    # import sys
    # sys.stdin = open("C.txt")
    print(main())

