def solve(s):
    n = len(s)
    total_sum = sum(int(digit) for digit in s) % 3
    if total_sum == 0:
        return s.lstrip('0') or '0'

    result = ''
    for remainder in range(1, 3):
        if total_sum == remainder:
            new_s = ''
            found = False
            for i in range(n):
                if int(s[i]) % 3 == remainder:
                    new_s = s[:i] + s[i+1:]
                    found = True
                    break
            if found:
                new_s = new_s.lstrip('0')
                if new_s:
                    result = max(result, new_s, key=lambda x: (len(x), x))
                elif s[i] == '0':
                    result = max(result, '0', key=lambda x: (len(x), x))

            new_s = ''
            count = 0
            for i in range(n):
                if int(s[i]) % 3 == 3 - remainder:
                    count += 1
                    if count == 2:
                        new_s = s[:i-1] + s[i+1:]
                        break
            if count >= 2:
                new_s = new_s.lstrip('0')
                if new_s:
                    result = max(result, new_s, key=lambda x: (len(x), x))

    if result:
        return result
    else:
        for i in range(n):
            if s[i] == '0':
                return '0'
        return '-1'

