def prime_factors(n):
    """Return a list of prime factors of n"""
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def k_factorization(n, k):
    """Return k integers whose product is n, or -1 if impossible"""
    factors = prime_factors(n)
    if len(factors) < k:
        return -1
    result = factors[:k-1]
    result.append(1)
    for f in factors[k-1:]:
        result[-1] *= f
    return result

def main():
    n, k = map(int, input().split())
    result = k_factorization(n, k)
    if result == -1:
        print(-1)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()

