    print(1, x, y)
    sys.stdout.flush()
    return input() == "TAK"

def divide(l, r):
    d = r - l + 1
    if d == 1:
        return l
    m = (l + r) // 2
    if ask(m, m + 1):
        return divide(l, m)
    else:
        return divide(m + 1, r)

def solve():
    n, k = line()
    x = divide(1, n)
    y = x
