def is_really_big(x, s):
    """Check if x is really big, i.e., x - sum_of_digits(x) >= s."""
    return x - sum_of_digits(x) >= s

def find_smallest_really_big(s):
    """Find the smallest really big number using a simple estimation and check."""
    # Start from s, as numbers less than s cannot be really big if s is large
    low = s
    # Simple exponential search to bracket the smallest really big number
    while not is_really_big(low, s):
        low *= 2
    # Binary search within the bracketed range
    left, right = low // 2, low
    while left <= right:
        mid = (left + right) // 2
        if is_really_big(mid, s):
            right = mid - 1
        else:
            left = mid + 1
    return left

