import heapq
import sys

def read_input():
    return map(int, sys.stdin.readline().strip().split())

def main():
    n, m = read_input()
    graph = [[] for _ in range(n)]
    in_degree = [0] * n

    for _ in range(m):
        u, v = read_input()
        u -= 1
        v -= 1
        graph[u].append(v)
        in_degree[v] += 1

    queue = []
    for i in range(n):
        if in_degree[i] == 0:
            heapq.heappush(queue, -i)

    labels = [0] * n
    label = n

    while queue:
        vertex = -heapq.heappop(queue)
        labels[vertex] = label
        label -= 1
        for neighbor in graph[vertex]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(queue, -neighbor)

    print(*labels)

if __name__ == "__main__":
    main()

