import itertools

def calc(d, a, k):
    return (d - 1) * len(a) - sum(i % d for i in a) <= k

def jumps(a):
    d = int(2 * a ** 0.55)
    while True:
        c = (a + d - 1) // d
        d = (a + c - 2) // (c - 1)
        if d >= a - 1:
            return
        yield d

def main():
    n, k = map(int, input().split())
    a = [i - 1 for i in map(int, input().split())]
    lb = int(max(a) ** 0.1 + 10)

    for d in range(lb, 0, -1):
        if calc(d, a, k):
            print(d)
