    for i in a:
        i += 1
        D.add(i + k + 1)
        d = int(2 * i ** 0.55)
        D.add(d)
        for j in jumps(i):
            D.add(j)
    D = sorted(D, reverse=True)

    a = [i + 1 for i in a]
    for d in D:
        if calc(d, [i - 1 for i in a], k):
            print(d)
            return

