def check_horizontal(n, m, grid):
    if n % 3 != 0:
        return False
    stripe_height = n // 3
    colors = set()
    for i in range(3):
        stripe_color = grid[i * stripe_height][0]
        for j in range(stripe_height):
            for k in range(m):
                if grid[i * stripe_height + j][k] != stripe_color:
                    return False
        colors.add(stripe_color)
    return len(colors) == 3

def check_vertical(n, m, grid):
    if m % 3 != 0:
