def count_hexagons(x1, y1, x2, y2):
    x_count = (x2 - x1) // 2 + 1
    y_count = (y2 - y1 + 1)
    total_count = x_count * y_count + (x_count - 1) * (y_count - 1)
    if (x2 - x1) % 2 == 0 and (y2 - y1) % 2 == 0:
        if ((x1 + y1) % 2 == 0):
            return total_count
        else:
            return total_count - 1
    else:
        return total_count

