import itertools
import sys

def generate_possible_numbers():
    digits = [str(i) for i in range(10)]
    possible_numbers = []
    for p in itertools.permutations(digits, 4):
        possible_numbers.append(''.join(p))
    return possible_numbers

def filter_numbers(possible_numbers, query, bulls, cows):
    filtered_numbers = []
    for num in possible_numbers:
        num_bulls = sum([1 for i in range(4) if num[i] == query[i]])
        num_cows = sum([1 for d in set(query) if d in num]) - num_bulls
        if num_bulls == bulls and num_cows == cows:
            filtered_numbers.append(num)
    return filtered_numbers

def main():
    possible_numbers = generate_possible_numbers()
    query_index = 0
    while True:
        query = possible_numbers[query_index]
        print(query)
        sys.stdout.flush()
        try:
            bulls, cows = map(int, input().split())
        except ValueError:
            break
        if bulls == 4 and cows == 0:
            break
        possible_numbers = filter_numbers(possible_numbers, query, bulls, cows)
        if not possible_numbers:
            break
        query_index = 0  # Always choose the first number from the filtered list

if __name__ == "__main__":
    main()

