    for _ in range(n):
        ti, Ti, xi, costi = map(int, input().split())

        if ti >= Ti:
            total_cost += costi + m * xi
        else:
            max_children_per_bus = Ti - ti
            if max_children_per_bus <= 0:
                total_cost += costi + m * xi
            else:
                buses_needed = (m + max_children_per_bus - 1) // max_children_per_bus
                cost_multiple_buses = buses_needed * costi
                cost_one_bus = costi + (m * xi if ti + m > Ti else 0)
                total_cost += min(cost_multiple_buses, cost_one_bus)

    print(total_cost)

