def get_inverse_permutation(q):
    n = len(q)
    q_inv = [0] * n
    for i in range(n):
        q_inv[q[i] - 1] = i + 1
    return q_inv

def apply_permutation(p, q):
    n = len(p)
    result = [0] * n
    for i in range(n):
        result[i] = p[q[i] - 1]
    return result

def main():
