def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def get_primes(n):
    primes = []
    num = 2
    while len(primes) < n:
        if is_prime(num):
            primes.append(num)
        num += 1
    return primes

def solve(n):
    primes = get_primes(10)
    dp = [[float('inf')] * (n + 1) for _ in range(len(primes) + 1)]
    dp[0][1] = 1

    for i in range(len(primes)):
        for j in range(1, n + 1):
            dp[i + 1][j] = min(dp[i + 1][j], dp[i][j])
            k = 2
            while j * k <= n:
                dp[i + 1][j * k] = min(dp[i + 1][j * k], dp[i][j] * (primes[i] ** (k - 1)))
                k += 1

    return dp[-1][n]

