def min_reorders(n, commands):
    stack = []
    expected_box = 1
    reorders = 0

    for command, *args in commands:
        if command == 'add':
            box = int(args[0])
            stack.append(box)
        else:
            if stack and stack[-1] == expected_box:
                stack.pop()
                expected_box += 1
            else:
                # Conceptually reorder by checking if the required box is in the stack
                if expected_box in stack:
                    reorders += 1
                    # Clear the stack up to the expected box
                    while stack[-1] != expected_box:
                        stack.pop()
                    stack.pop()
                    expected_box += 1
                else:
                    # This should not happen given the problem constraints
                    raise ValueError("Expected box not in stack")

    return reorders

