def maximize_sum_of_digits(x):
    x_str = str(x)
    n = len(x_str)
    max_sum = sum(int(digit) for digit in x_str)
    max_num = x

    for i in range(n):
        if x_str[i] != '0':
            new_num_str = x_str[:i] + str(int(x_str[i]) - 1) + '9' * (n - i - 1)
            new_num = int(new_num_str)
            if new_num <= x:
                new_sum = sum(int(digit) for digit in new_num_str)
                if new_sum > max_sum:
                    max_sum = new_sum
                    max_num = new_num
                elif new_sum == max_sum and new_num > max_num:
                    max_num = new_num

    return max_num

